for memo in ['tet28-modification-target-census.md','tet29-imported-mechanism-premises.md']:
    snap=base+memo+'.tetel/'
    ev=base+memo+'.evidence.jsonl'
    claims={}
    order=[]
    for line in open(snap+'claims.jsonl'):
        e=json.loads(line)
        if e['event']=='Create':
            claims[e['id']]={'prop':e['prop'],'t':e['timestamp'],'wd':False}
            order.append(e['id'])
        elif e['event']=='Revise':
            c=claims[e['id']]
            if e.get('prop') is not None: c['prop']=e['prop']
            c['t']=e['timestamp']
        elif e['event']=='Withdraw':
            claims[e['id']]['wd']=True
    firstproof={}
    for line in open(ev):
        line=line.strip()
        if not line: continue
        s=json.loads(line); sub=s['subject'][0]; cid=sub['name']; dg=sub['digest']['sha256']
        c=claims.get(cid)
        if not c: continue
        cur=hashlib.sha256(c['prop'].encode()).hexdigest()
        if dg==cur or dg=='':
            t=s['predicate']['timestamp']
            firstproof[cid]=min(firstproof.get(cid,t),t)
    blocks={}; border=[]
    for line in open(snap+'prose.jsonl'):
        e=json.loads(line)
        if e['event']=='Create':
            blocks[e['id']]={'heading':e['heading'],'cite':e.get('cite',[]),'t':e['timestamp'],'rev':0}
            border.append(e['id'])
        else:
            b=blocks[e['id']]; b['t']=e['timestamp']; b['rev']+=1
            if e.get('cite') is not None: b['cite']=e['cite']
    print('==',memo,'blocks',len(blocks),'claims',len(claims),'first-proof known for',len(firstproof))
    n=0
    for bid in border:
        b=blocks[bid]
        if b['heading'] or not b['cite']: continue
        cited=[c for c in b['cite'] if c in claims]
        if not cited or len(cited)!=len(b['cite']): print('   ',bid,'cites unresolved',b['cite']); continue
        if not all(c in firstproof for c in cited): continue
        anchor=max(firstproof[c] for c in cited)
        if b['t']>anchor:
            n+=1
            print('    REPORT',bid,'text t=%d rev=%d'%(b['t'],b['rev']),'anchor=%d'%anchor,'(+%ds)'%(b['t']-anchor),'cites',cited)
    print('    total reported:',n)

