/// `tetel prose --revise <id> --why <text> [new text, from stdin by default]`.
/// Revise a block's text, and optionally its citations.
///
/// `cite: None` leaves citations untouched. Until this parameter existed,
/// a paragraph created without a citation could never be given one —
/// `--cites` was accepted alongside `--revise` and silently discarded —
/// which made `tetel review`'s own instruction ("mint the missing claim
/// and cite it") unreachable for existing prose.
pub fn revise(
    workspace_dir: &Path,
    id: &str,
    new_text: &str,
    why: &str,
    cite: Option<Vec<String>>,
) -> Result<(), AuthoringError> {
    if !exists(workspace_dir, id)? {
        return Err(workspace::refuse(workspace_dir, "prose", format!("no such prose block: {id}")));
    }
    if why.trim().is_empty() {
        return Err(workspace::refuse(workspace_dir, "prose", "--revise requires --why (revisions must explain themselves)"));
    }
    let event = ProseEvent::Revise {
        id: id.to_string(),
        text: new_text.to_string(),
        why: why.to_string(),
        cite,
        timestamp: workspace::now_unix(),
    };
    workspace::append_jsonl(&log_path(workspace_dir), &event)?;
    Ok(())
}

/// What `tetel prose` was asked to do — append a paragraph, append a
/// heading, or revise an existing block. `text` arrives already resolved
/// since. Rendering two columns nothing can ever fill put dead wiring in
/// front of every reader and made `check` print one unresolvable line per
/// claim.
const HEADER_AUTHORED: [&str; 3] = ["ID", "Proposition", "Status"];

/// Sentinel `Domain`/`Extent` cell text, for a ledger that *has* those
/// columns and has nothing to put in them.
///
/// `compose::render` no longer writes it: a tetel-authored ledger omits
/// the columns entirely ([`HEADER_AUTHORED`]), because the authoring
/// model has no scope field and two permanently unfillable cells are
/// dead wiring in a document a human reads.
///
/// Kept because a hand-maintained corpus ledger may carry the columns and
/// legitimately declare nothing in them — there,
/// `checks::claims_without_declared_scope` still names the gap plainly
/// rather than let an empty-seeming cell pass as an unearned claim of
/// total coverage.
pub const NO_SCOPE_DECLARED: &str = "not declared (tetel's authoring model has no domain/extent field on a claim)";

/// Split one `|`-delimited table row into its cells. Respects a backtick
/// span (a `|` inside `` `...` `` is not a separator) and a `\|` escape,
/// and drops the empty leading/trailing cell markdown table syntax
/// produces from the row's bounding pipes.
fn split_row_cells(line: &str) -> Vec<String> {
    let line = line.trim();
    let mut cells = Vec::new();
    let mut current = String::new();
    let mut in_backtick = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '\\' if chars.peek() == Some(&'|') => {
                current.push('|');
                chars.next();
            }
            '`' => {
                in_backtick = !in_backtick;
                current.push('`');
            }
            '|' if !in_backtick => {
                cells.push(std::mem::take(&mut current).trim().to_string());
            }
            _ => current.push(c),
        }
    }
    cells.push(current.trim().to_string());
    if cells.first().is_some_and(String::is_empty) {
        cells.remove(0);
    }
    if cells.last().is_some_and(String::is_empty) {
        cells.pop();
    }
    cells
}

fn is_table_row(line: &str) -> bool {
    line.trim_start().starts_with('|')
}

/// True if every cell of a row is made up only of `-`, `:` and spaces —
/// the header/body separator row markdown tables require.
fn is_separator_row(cells: &[String]) -> bool {
    !cells.is_empty()
        && cells
            .iter()
            .all(|c| !c.is_empty() && c.chars().all(|ch| ch == '-' || ch == ':'))
}

